"use client";

import * as React from "react";
import { ArrowDown, Search } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * LOG STREAM: a live tail you can actually read
 *
 *   tail      lines arrive in batches, one render per frame
 *             however fast they come, and the view stays
 *             pinned to the newest line
 *   read      scroll up and the view lets go: lines keep
 *             arriving underneath, and a "↓ 128 new" pill rises
 *             with its count rolling; one tap takes you back
 *             down and pins it again
 *   pause     Live → Paused holds new lines back without
 *             losing them ("Paused · 42 waiting"); Live plays
 *             them in
 *   filter    level chips count as lines arrive and hide what
 *             you don't need; search marks every match ("/"
 *             focuses it)
 *   open      a line with data opens into its fields under it,
 *             by height, with Copy
 *   earlier   reach the top and older lines load in above
 *             without moving what you're reading
 *
 * Lines are plain records; subscribe() feeds them from SSE, a
 * WebSocket, Supabase Realtime or a poll.
 * ───────────────────────────────────────────────────────── */

export type LogLevel = "debug" | "info" | "warn" | "error";
export type DateLike = Date | string | number;

export interface LogLine {
  id: string;
  at: DateLike;
  level: LogLevel;
  message: string;
  /** Where it came from: "api", "worker", "cron". */
  source?: string;
  /** Fields shown when the line is opened. */
  data?: Record<string, unknown>;
}

export interface LogStreamProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue"
> {
  /** Lines to start with, oldest first. */
  defaultValue?: LogLine[];
  /** Starts the tail: call push with new lines; return a function that stops it. */
  subscribe?: (push: (lines: LogLine | LogLine[]) => void) => () => void;
  /** Loads lines older than the first one shown, oldest first; an empty list means there are no more. */
  loadEarlier?: (before: LogLine) => Promise<LogLine[]>;
  /** Lines kept in memory while you're at the bottom. */
  max?: number;
  /** The scrolling area's height. */
  height?: number | string;
  title?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const LEVELS: LogLevel[] = ["error", "warn", "info", "debug"];
const NAMES: Record<LogLevel, string> = {
  error: "Errors",
  warn: "Warnings",
  info: "Info",
  debug: "Debug",
};
const TONE: Record<LogLevel, string> = {
  error: "text-red-600 dark:text-red-400",
  warn: "text-amber-700 dark:text-amber-400",
  info: "text-muted-foreground",
  debug: "text-muted-foreground/60",
};
const TICK: Record<LogLevel, string> = {
  error: "bg-red-500",
  warn: "bg-amber-500",
  info: "bg-transparent",
  debug: "bg-transparent",
};
const NONE: LogLine[] = [];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const toTime = (d: DateLike) =>
  d instanceof Date
    ? d.getTime()
    : typeof d === "number"
      ? d
      : new Date(d).getTime();
const pad = (n: number, w = 2) => String(n).padStart(w, "0");
const clock = (d: DateLike) => {
  const t = new Date(toTime(d));
  return `${pad(t.getHours())}:${pad(t.getMinutes())}:${pad(t.getSeconds())}.${pad(t.getMilliseconds(), 3)}`;
};

/** The message with every match marked. */
function Marked({ text, query }: { text: string; query: string }) {
  if (!query) return <>{text}</>;
  const parts: React.ReactNode[] = [];
  const lower = text.toLowerCase();
  const q = query.toLowerCase();
  let i = 0;
  let at = lower.indexOf(q);
  while (at !== -1) {
    if (at > i) parts.push(text.slice(i, at));
    parts.push(
      <mark key={at} className="rounded-[3px] bg-primary/15 text-inherit">
        {text.slice(at, at + q.length)}
      </mark>,
    );
    i = at + q.length;
    at = lower.indexOf(q, i);
  }
  parts.push(text.slice(i));
  return <>{parts}</>;
}

function Value({ v }: { v: unknown }) {
  if (v === null || v === undefined)
    return <span className="text-muted-foreground">{String(v)}</span>;
  if (typeof v === "number" || typeof v === "boolean")
    return <span className="text-primary">{String(v)}</span>;
  if (typeof v === "string")
    return <span className="text-foreground">&quot;{v}&quot;</span>;
  return <span className="text-foreground">{JSON.stringify(v)}</span>;
}

interface RowProps {
  line: LogLine;
  open: boolean;
  query: string;
  enter: boolean;
  reduced: boolean;
  toggle: (id: string) => void;
}

const Row = React.memo(function Row({
  line,
  open,
  query,
  enter,
  reduced,
  toggle,
}: RowProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const [copied, setCopied] = React.useState(false);
  const has = Boolean(line.data && Object.keys(line.data).length);

  React.useLayoutEffect(() => {
    if (enter && !reduced)
      ref.current?.animate(
        [
          { opacity: 0, filter: "blur(2px)" },
          { opacity: 1, filter: "blur(0px)" },
        ],
        { duration: 260, easing: EASE },
      );
  }, []);
  React.useEffect(() => {
    if (!copied) return;
    const timer = window.setTimeout(() => setCopied(false), 1400);
    return () => window.clearTimeout(timer);
  }, [copied]);

  const head = (
    <>
      <span
        aria-hidden="true"
        className={`absolute top-1.5 bottom-1.5 left-0 w-0.5 rounded-full ${TICK[line.level]}`}
      />
      <time
        dateTime={new Date(toTime(line.at)).toISOString()}
        className="hidden w-[6.6rem] shrink-0 text-muted-foreground tabular-nums @md:block"
      >
        {clock(line.at)}
      </time>
      <span className={`w-[2.6rem] shrink-0 uppercase ${TONE[line.level]}`}>
        {line.level === "error" ? "err" : line.level}
      </span>
      {line.source && (
        <span className="hidden w-[4.5rem] shrink-0 truncate text-muted-foreground @sm:block">
          {line.source}
        </span>
      )}
      <span className="min-w-0 flex-1 truncate text-foreground">
        <Marked text={line.message} query={query} />
      </span>
    </>
  );

  return (
    <div
      ref={ref}
      role="listitem"
      className="[contain-intrinsic-size:auto_28px] [content-visibility:auto]"
    >
      {has ? (
        <button
          type="button"
          aria-expanded={open}
          onClick={() => toggle(line.id)}
          className={`relative flex h-7 w-full cursor-pointer items-center gap-3 rounded-[6px] pr-2 pl-3 text-left transition-colors hover:bg-accent/70 ${open ? "bg-accent/70" : ""} ${FOCUS}`}
        >
          {head}
        </button>
      ) : (
        <div className="relative flex h-7 items-center gap-3 pr-2 pl-3">
          {head}
        </div>
      )}
      {has && (
        <div
          className="grid"
          inert={!open}
          style={{
            gridTemplateRows: open ? "1fr" : "0fr",
            transition: reduced ? "none" : `grid-template-rows 320ms ${EASE}`,
          }}
        >
          <div className="min-h-0 min-w-0 overflow-clip">
            {open && (
              <div className="relative my-1 ml-3 rounded-[10px] px-3 py-2 shadow-[inset_0_0_0_1px_var(--border)] @md:ml-[7.6rem]">
                <button
                  type="button"
                  onClick={async () => {
                    try {
                      await navigator.clipboard.writeText(
                        JSON.stringify(
                          {
                            at: new Date(toTime(line.at)).toISOString(),
                            level: line.level,
                            source: line.source,
                            message: line.message,
                            ...line.data,
                          },
                          null,
                          2,
                        ),
                      );
                      setCopied(true);
                    } catch {
                      /* The fields are on screen to select. */
                    }
                  }}
                  className={`absolute top-1.5 right-1.5 h-6 cursor-pointer rounded-full px-2 font-sans text-[11px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
                >
                  <TextMorph>{copied ? "Copied" : "Copy"}</TextMorph>
                </button>
                <dl className="grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-0.5 pr-14">
                  {Object.entries(line.data!).map(([k, v]) => (
                    <React.Fragment key={k}>
                      <dt className="text-muted-foreground">{k}</dt>
                      <dd className="min-w-0 break-all">
                        <Value v={v} />
                      </dd>
                    </React.Fragment>
                  ))}
                </dl>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
});

export function LogStream({
  defaultValue = NONE,
  subscribe,
  loadEarlier,
  max = 1000,
  height = 420,
  title = "Logs",
  className = "",
  ...props
}: LogStreamProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [lines, setLines] = React.useState<LogLine[]>(defaultValue);
  const [paused, setPaused] = React.useState(false);
  const [held, setHeld] = React.useState(0);
  const [below, setBelow] = React.useState(0);
  const [query, setQuery] = React.useState("");
  const [shown, setShown] = React.useState<Set<LogLevel>>(
    () => new Set(LEVELS),
  );
  const [open, setOpen] = React.useState<Set<string>>(() => new Set());
  const [loading, setLoading] = React.useState(false);
  const [noMore, setNoMore] = React.useState(!loadEarlier);
  const [fresh, setFresh] = React.useState<Set<string>>(() => new Set());
  const [announce, setAnnounce] = React.useState("");

  const viewRef = React.useRef<HTMLDivElement>(null);
  const searchRef = React.useRef<HTMLInputElement>(null);
  const sentinelRef = React.useRef<HTMLDivElement>(null);
  const incoming = React.useRef<LogLine[]>([]);
  const holding = React.useRef<LogLine[]>([]);
  const frame = React.useRef(0);
  const stuck = React.useRef(true);
  const intent = React.useRef(0);
  const keep = React.useRef<number | null>(null);
  const pausedRef = React.useRef(paused);
  const linesRef = React.useRef(lines);
  React.useLayoutEffect(() => {
    pausedRef.current = paused;
    linesRef.current = lines;
  });

  // Stable, so the memoised rows don't re-render when it's passed down.
  const toggle = React.useCallback(
    (lineId: string) =>
      setOpen((o) => {
        const next = new Set(o);
        if (next.has(lineId)) next.delete(lineId);
        else next.add(lineId);
        return next;
      }),
    [],
  );

  // New lines wait for the next frame, so a burst is one render.
  const flush = React.useCallback(() => {
    frame.current = 0;
    const batch = incoming.current;
    incoming.current = [];
    if (!batch.length) return;
    setLines((prev) => {
      const next = prev.concat(batch);
      // Trim only while pinned to the bottom, so lines never vanish from under someone reading.
      return stuck.current && next.length > max
        ? next.slice(next.length - max)
        : next;
    });
    setFresh(batch.length <= 12 ? new Set(batch.map((l) => l.id)) : new Set());
    if (!stuck.current) setBelow((b) => b + batch.length);
  }, [max]);

  const push = React.useCallback(
    (input: LogLine | LogLine[]) => {
      const list = Array.isArray(input) ? input : [input];
      if (pausedRef.current) {
        holding.current.push(...list);
        setHeld(holding.current.length);
        return;
      }
      incoming.current.push(...list);
      if (!frame.current) frame.current = requestAnimationFrame(flush);
    },
    [flush],
  );

  React.useEffect(() => {
    if (!subscribe) return;
    const stop = subscribe(push);
    return () => {
      stop();
      cancelAnimationFrame(frame.current);
      frame.current = 0;
    };
  }, [subscribe, push]);

  // Pinned: every commit ends on the newest line. Loading earlier: the line you were reading stays put.
  React.useLayoutEffect(() => {
    const view = viewRef.current;
    if (!view) return;
    if (keep.current !== null) {
      view.scrollTop += view.scrollHeight - keep.current;
      keep.current = null;
      return;
    }
    if (stuck.current) view.scrollTop = view.scrollHeight;
  }, [lines, shown, query]);

  const onScroll = () => {
    const view = viewRef.current;
    if (!view) return;
    const atBottom =
      view.scrollHeight - view.scrollTop - view.clientHeight < 24;
    if (atBottom) {
      stuck.current = true;
      setBelow(0);
    } else if (performance.now() - intent.current < 900) {
      // Only a scroll the reader made lets go; content changing size doesn't.
      stuck.current = false;
    }
  };
  const meant = () => (intent.current = performance.now());

  const toBottom = () => {
    const view = viewRef.current;
    if (!view) return;
    stuck.current = true;
    setBelow(0);
    view.scrollTo({
      top: view.scrollHeight,
      behavior: reduced ? "auto" : "smooth",
    });
  };

  const setLive = (live: boolean) => {
    setPaused(!live);
    if (live) {
      const waiting = holding.current;
      holding.current = [];
      setHeld(0);
      if (waiting.length) {
        incoming.current.push(...waiting);
        if (!frame.current) frame.current = requestAnimationFrame(flush);
      }
      setAnnounce(
        waiting.length ? `Live. ${waiting.length} lines played in.` : "Live.",
      );
    } else setAnnounce("Paused. New lines are held.");
  };

  // Older lines, when the top comes into view.
  React.useEffect(() => {
    const el = sentinelRef.current;
    const view = viewRef.current;
    if (!el || !view || !loadEarlier || noMore) return;
    const observer = new IntersectionObserver(
      async ([entry]) => {
        if (!entry.isIntersecting || loading) return;
        const first = linesRef.current[0];
        if (!first) return;
        setLoading(true);
        try {
          const older = await loadEarlier(first);
          if (!older.length) setNoMore(true);
          else {
            keep.current = viewRef.current?.scrollHeight ?? null;
            setFresh(new Set());
            setLines((prev) => older.concat(prev));
          }
        } finally {
          setLoading(false);
        }
      },
      { root: view, rootMargin: "120px 0px 0px 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [loadEarlier, noMore, loading]);

  React.useEffect(() => () => cancelAnimationFrame(frame.current), []);

  const counts = React.useMemo(() => {
    const c: Record<LogLevel, number> = {
      error: 0,
      warn: 0,
      info: 0,
      debug: 0,
    };
    for (const l of lines) c[l.level]++;
    return c;
  }, [lines]);
  const q = query.trim();
  const visible = React.useMemo(
    () =>
      lines.filter(
        (l) =>
          shown.has(l.level) &&
          (!q ||
            l.message.toLowerCase().includes(q.toLowerCase()) ||
            l.source?.toLowerCase().includes(q.toLowerCase())),
      ),
    [lines, shown, q],
  );

  return (
    <div
      className={`@container w-full rounded-[22px] border border-border bg-background text-foreground ${className}`}
      onKeyDown={(e) => {
        if (e.key === "/" && document.activeElement !== searchRef.current) {
          e.preventDefault();
          searchRef.current?.focus();
        } else if (
          e.key === "Escape" &&
          document.activeElement === searchRef.current &&
          query
        ) {
          setQuery("");
        }
      }}
      {...props}
    >
      <div className="flex flex-wrap items-center gap-2 border-b border-border px-3 py-2.5 @md:px-4">
        <button
          type="button"
          aria-pressed={!paused}
          onClick={() => setLive(paused)}
          className={`inline-flex h-7 shrink-0 cursor-pointer items-center gap-2 rounded-full px-2.5 text-[12px] font-medium shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
        >
          <span
            className="relative grid size-2 place-items-center"
            aria-hidden="true"
          >
            <span
              className={`size-1.5 rounded-full transition-colors duration-300 ${paused ? "bg-muted-foreground" : "bg-emerald-500"}`}
            />
            {!paused && !reduced && (
              <span className="absolute inset-0 rounded-full bg-emerald-500 opacity-40 animate-[ui-ping_1.6s_ease-out_infinite]" />
            )}
          </span>
          <TextMorph>{paused ? "Paused" : "Live"}</TextMorph>
          <span
            aria-hidden={!(paused && held) || undefined}
            className="-ml-2 inline-grid text-muted-foreground"
            style={{
              gridTemplateColumns: paused && held ? "1fr" : "0fr",
              opacity: paused && held ? 1 : 0,
              transition: reduced
                ? "none"
                : `grid-template-columns 380ms ${EASE}, opacity 240ms ${EASE}`,
            }}
          >
            <span className="min-w-0 [clip-path:inset(-4px_0)]">
              <span className="inline-flex items-baseline pl-2 font-normal whitespace-nowrap tabular-nums">
                ·&nbsp;
                <NumberRoll value={held || 1} />
                &nbsp;waiting
              </span>
            </span>
          </span>
        </button>

        <label className="flex h-7 min-w-[9rem] flex-1 items-center gap-1.5 rounded-full px-2.5 shadow-[inset_0_0_0_1px_var(--border)] transition-shadow focus-within:shadow-[inset_0_0_0_1px_var(--ring)]">
          <Search
            className="size-3.5 shrink-0 text-muted-foreground"
            strokeWidth={1.75}
            aria-hidden="true"
          />
          <span className="sr-only">Search {title}</span>
          <input
            ref={searchRef}
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search"
            className="h-full min-w-0 flex-1 bg-transparent text-[16px] text-foreground outline-none placeholder:text-muted-foreground/70 [@media(pointer:fine)]:text-[12.5px] [&::-webkit-search-cancel-button]:hidden"
          />
          <kbd
            aria-hidden="true"
            className="hidden rounded-[5px] px-1 font-mono text-[10.5px] text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)] [@media(pointer:fine)]:block"
          >
            /
          </kbd>
        </label>

        <div
          role="group"
          aria-label="Levels"
          className="-mx-1 flex max-w-full items-center gap-1 overflow-x-auto px-1 [scrollbar-width:none] @lg:mx-0 @lg:px-0"
        >
          {LEVELS.map((lv) => {
            const on = shown.has(lv);
            return (
              <button
                key={lv}
                type="button"
                aria-pressed={on}
                onClick={() =>
                  setShown((s) => {
                    const next = new Set(s);
                    if (next.has(lv)) next.delete(lv);
                    else next.add(lv);
                    return next;
                  })
                }
                className={`inline-flex h-7 shrink-0 cursor-pointer items-center gap-1.5 rounded-full px-2.5 text-[12px] font-medium whitespace-nowrap transition-[background-color,color,box-shadow,opacity] duration-200 ${FOCUS} ${
                  on
                    ? "bg-accent text-foreground shadow-[inset_0_0_0_1px_var(--border)]"
                    : "text-muted-foreground opacity-60 hover:opacity-100"
                }`}
              >
                {(lv === "error" || lv === "warn") && (
                  <span
                    aria-hidden="true"
                    className={`size-1.5 rounded-full ${TICK[lv]}`}
                  />
                )}
                {NAMES[lv]}
                <span className="font-normal text-muted-foreground tabular-nums">
                  <NumberRoll value={counts[lv]} />
                </span>
              </button>
            );
          })}
        </div>
      </div>

      <div className="relative">
        <div
          ref={viewRef}
          onScroll={onScroll}
          onWheel={meant}
          onTouchMove={meant}
          onKeyDown={meant}
          onPointerDown={(e) => e.target === e.currentTarget && meant()}
          tabIndex={0}
          aria-label={`${title}, newest at the bottom`}
          className={`overflow-y-auto overscroll-contain px-1.5 py-1.5 font-mono text-[12px] @md:px-2 ${FOCUS} focus-visible:ring-inset`}
          style={{ height }}
        >
          <div ref={sentinelRef} aria-hidden="true" className="h-px" />
          {loadEarlier && (
            <p className="flex h-7 items-center justify-center gap-2 font-sans text-[11.5px] text-muted-foreground">
              {noMore
                ? "Start of the log"
                : loading
                  ? "Loading earlier lines"
                  : "Scroll up for earlier lines"}
            </p>
          )}
          <div role="list" aria-label={title} id={`${id}-list`}>
            {visible.map((l) => (
              <Row
                key={l.id}
                line={l}
                open={open.has(l.id)}
                query={q}
                enter={fresh.has(l.id)}
                reduced={reduced}
                toggle={toggle}
              />
            ))}
          </div>
          {!visible.length && (
            <p className="flex h-24 items-center justify-center font-sans text-[12.5px] text-muted-foreground">
              {lines.length
                ? "No lines match."
                : paused
                  ? "Paused."
                  : "Waiting for the first line…"}
            </p>
          )}
        </div>

        {/* Lines that arrived while you were reading further up. */}
        <div className="pointer-events-none absolute inset-x-0 bottom-3 flex justify-center">
          <button
            type="button"
            onClick={toBottom}
            tabIndex={below ? 0 : -1}
            aria-hidden={!below || undefined}
            className={`pointer-events-auto inline-flex h-8 cursor-pointer items-center gap-1.5 rounded-full bg-background px-3 text-[12px] font-medium shadow-[inset_0_0_0_1px_var(--border)] transition-[transform,opacity] hover:bg-accent ${FOCUS} ${below ? "" : "pointer-events-none"}`}
            style={{
              opacity: below ? 1 : 0,
              transform: below ? "none" : "translateY(10px) scale(0.96)",
              transitionDuration: reduced ? "0ms" : "420ms",
              transitionTimingFunction: EASE,
            }}
          >
            <ArrowDown
              className="size-3.5"
              strokeWidth={2}
              aria-hidden="true"
            />
            <span className="inline-flex items-baseline tabular-nums">
              <NumberRoll value={below || 1} />
              &nbsp;new
            </span>
          </button>
        </div>
      </div>

      <span className="sr-only" role="status">
        {announce}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

